// Generates crates/opencode/src/generated/mime.rs: the extension table of `FSUtil.mimeType`
// (packages/util/src/fs-util.ts), which is mime-types' `lookup`, read off the very module the TS reference loads, so
// its conflict resolution between mime-db sources is the reference's.
//
// usage: bun src/mime.ts            write the generated file
//        bun src/mime.ts --check    fail if the checked-in file differs from a fresh generation
import { readFileSync, writeFileSync } from "node:fs"
import { join, resolve } from "node:path"

const ref = resolve(process.env.REFERENCE ?? join(import.meta.dir, "../../../.reference"))
const mime = (await import(join(ref, "packages/util/node_modules/mime-types/index.js"))).default as {
  types: Record<string, string>
}
const output = join(import.meta.dir, "../../crates/opencode/src/generated/mime.rs")

const entries = Object.entries(mime.types).toSorted(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
const lines = [
  "// @generated by port/rust/gen/src/mime.ts from the TS reference's mime-types module.",
  "// Do not edit: regenerate instead.",
  "",
  "/// Lower-case extension (without the dot) to media type, sorted by extension.",
  "pub const TYPES: &[(&str, &str)] = &[",
  ...entries.map(([extension, type]) => `    (${JSON.stringify(extension)}, ${JSON.stringify(type)}),`),
  "];",
  "",
]
const text = lines.join("\n")
if (process.argv.includes("--check")) {
  if (readFileSync(output, "utf8") !== text) throw new Error(`${output} is out of date`)
} else {
  writeFileSync(output, text)
  console.log(`wrote ${output}: ${entries.length} extensions`)
}
